export interface StreamingMarkdownOptions {
  /**
   * Preserve completed block output instead of rendering it for every update.
   * Available in stream-markdown 2.4.1.
   */
  freezeCompletedBlocks?: boolean;
}

export declare function renderStreamingMarkdown(
  blocks: Array<{ completed: boolean; updates: number }>,
  options?: StreamingMarkdownOptions,
): { completedBlockRenderCount: number };
